            result = [[0] * self.m for _ in range(self.n)]
            status = gsl.linalg_cholesky_decomp(ctypes.byref(self),
                                                  (c_double * len(result))(*[item for sublist in result for item in sublist]),
                                                  ctypes.byref(c_int()))
            if status == 0:
