def dot_product(vector_x, vector_y):
    if len(vector_x) != len(vector_y):
        raise ValueError("Vectors must be of the same length")
    vector_x_c = (ctypes.c_double * len(vector_x))(*vector_x)
    vector_y_c = (ctypes.c_double * len(vector_y))(*vector_y)
    result = libgslcblas.cblas_ddot(len(vector_x), vector_x_c, 1, vector_y_c, 1)
    return float(result)

