import ctypes

cdef extern from 'gsl/gsl_rstat.h':
    void gsl_rstat_quantile_alloc(void** workspace)
    void gsl_rstat_quantile_reset(void* workspace)
    void gsl_rstat_quantile_add(void* workspace, double x)
    double gsl_rstat_quantile_get(const void* workspace, double p)
    void gsl_rstat_quantile_free(void* workspace)

class GslRstatQuantileWorkspace:
    def __init__(self):
        self.workspace = ctypes.c_void_p(None)

    def alloc(self):
        gsl_rstat_quantile_alloc(ctypes.byref(self.workspace))

    def reset(self):
        gsl_rstat_quantile_reset(self.workspace.value)

    def add(self, x):
        gsl_rstat_quantile_add(self.workspace.value, x)

    def get(self, p):
        return gsl_rstat_quantile_get(self.workspace.value, p)

    def free(self):
        gsl_rstat_quantile_free(self.workspace.value)

# Load GSL libraries
libgslcblas = ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=ctypes.RTLD_GLOBAL)
gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")

def compute_quantile(p, values):
    workspace = GslRstatQuantileWorkspace()
    try:
        workspace.alloc()
        for value in values:
            workspace.add(value)
        quantile = workspace.get(p)
    finally:
        workspace.free()
    return quantile

